import { Agent } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";
import * as dotenv from "dotenv";

dotenv.config();

export async function redactPii(input: string): Promise<string> {
    const agent = new Agent({
        id: "pii-redactor",
        name: "PII Redactor",
        instructions: "You are a PII redaction agent. Your job is to take transcribed audio text and replace any Personally Identifiable Information (PII) such as emails, phone numbers, and names with '[REDACTED]'. Return ONLY the redacted text, with no additional commentary.",
        model: openai("gpt-4o-mini"),
    });

    const result = await agent.generateText(input);
    return result.text;
}

// Test
if (require.main === module) {
    redactPii("My name is John Doe and my email is john.doe@example.com. Call me at 555-123-4567.")
        .then(console.log)
        .catch(console.error);
}

